def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract opponent's moves for fast access
    # Use recent window to detect state
    opp_last = history[-1][1]
    my_last = history[-1][0]

    # Count total statistics
    opp_c = 0
    my_c = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1
    opp_d = n - opp_c

    # Detect an always-defect opponent quickly
    if n >= 3 and opp_c == 0:
        return 'D'

    # Detect an always-cooperate / nearly always-cooperate opponent
    if n >= 6 and opp_d == 0:
        # Exploit near the end, but keep cooperation early to build score
        if n >= 92:
            return 'D'
        return 'C'

    # Count consecutive opponent defections at the end
    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    # Count consecutive opponent cooperations at the end
    opp_streak_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_streak_c += 1
        else:
            break

    # Recent window statistics (last 8)
    recent = history[-8:] if n >= 8 else history
    rec_len = len(recent)
    rec_opp_d = 0
    for m, o in recent:
        if o == 'D':
            rec_opp_d += 1
    rec_opp_c = rec_len - rec_opp_d

    remaining = 100 - n

    # Endgame exploitation. In final rounds, defect against cooperative opponents.
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        # Against opponents who have been cooperative, exploit
        if opp_c * 10 >= n * 7:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'
    if remaining <= 6:
        if opp_c * 10 >= n * 6:
            return 'D'
        if opp_streak_d >= 1:
            return 'D'
        return 'C'

    # If opponent has been very cooperative, mostly cooperate but occasionally
    # probe. Probes should be rare enough not to destroy trust.
    if n >= 10 and opp_d * 10 <= n:
        # Very cooperative opponent, but ensure we don't let them exploit
        if my_last == 'D' and opp_last == 'D':
            return 'C'
        # Rare deterministic probe to test for exploitation
        if n > 25 and n % 19 == 0 and remaining > 15:
            return 'D'
        return 'C'

    # If opponent is heavily defecting, defect back.
    if opp_d * 2 > n:
        # But occasionally try to break out of defection spirals
        if opp_streak_d >= 4 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # If opponent just defected
    if opp_last == 'D':
        # Strong retaliation against recent sustained defection
        if opp_streak_d >= 3:
            return 'D'
        # Moderate punishment for short defection streaks
        if opp_streak_d == 2:
            return 'D'
        # Single defection: retaliate but with some forgiveness if opponent
        # has been generally cooperative
        if opp_c * 10 >= n * 6:
            # Forgive occasionally to restore cooperation
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated
    if opp_last == 'C':
        # If we defected last and they still cooperated, continue cooperating
        # to groom them, but avoid being repeatedly exploited
        if my_last == 'D':
            if rec_opp_d >= 4:
                return 'D'
            return 'C'
        # If mutual cooperation, continue but probe occasionally
        if my_last == 'C':
            # Probe only if opponent has shown some defection tolerance
            if n > 30 and remaining > 20 and opp_d > 0:
                if n % 23 == 0 and rng.random() < 0.5:
                    return 'D'
            return 'C'

    return 'C'
